// audio.js - every sound is generated by code (Web Audio API), no files needed.

const CROWD_BASE = 0.035;

let audioContext = null;
let masterGain = null;
let crowdGain = null;
let noiseBuffer = null;
let muted = false;

function createNoiseBuffer() {
  const length = Math.floor(audioContext.sampleRate * 1.5);
  const buffer = audioContext.createBuffer(1, length, audioContext.sampleRate);
  const data = buffer.getChannelData(0);
  for (let i = 0; i < length; i++) {
    data[i] = Math.random() * 2 - 1;
  }
  return buffer;
}

function startCrowd() {
  const source = audioContext.createBufferSource();
  source.buffer = noiseBuffer;
  source.loop = true;
  const filter = audioContext.createBiquadFilter();
  filter.type = 'bandpass';
  filter.frequency.value = 500;
  filter.Q.value = 0.6;
  crowdGain = audioContext.createGain();
  crowdGain.gain.value = CROWD_BASE;
  source.connect(filter);
  filter.connect(crowdGain);
  crowdGain.connect(masterGain);
  source.start();
}

// Browsers only allow audio after a user action, so we start it on the first one.
function ensureAudio() {
  try {
    if (!audioContext) {
      const AudioContextClass = window.AudioContext || window.webkitAudioContext;
      if (!AudioContextClass) return false;
      audioContext = new AudioContextClass();
      masterGain = audioContext.createGain();
      masterGain.gain.value = muted ? 0 : 0.8;
      masterGain.connect(audioContext.destination);
      noiseBuffer = createNoiseBuffer();
      startCrowd();
    }
    if (audioContext.state === 'suspended') audioContext.resume();
    return true;
  } catch (error) {
    return false;
  }
}

['keydown', 'pointerdown', 'touchstart'].forEach((eventName) => {
  window.addEventListener(eventName, ensureAudio, { passive: true });
});

function playTone(frequency, endFrequency, duration, type, volume, delay) {
  const start = audioContext.currentTime + (delay || 0);
  const oscillator = audioContext.createOscillator();
  const gain = audioContext.createGain();
  oscillator.type = type;
  oscillator.frequency.setValueAtTime(frequency, start);
  oscillator.frequency.exponentialRampToValueAtTime(Math.max(1, endFrequency), start + duration);
  gain.gain.setValueAtTime(0.0001, start);
  gain.gain.exponentialRampToValueAtTime(volume, start + 0.01);
  gain.gain.exponentialRampToValueAtTime(0.0001, start + duration);
  oscillator.connect(gain);
  gain.connect(masterGain);
  oscillator.start(start);
  oscillator.stop(start + duration + 0.02);
}

function playNoise(duration, volume, filterType, filterFrequency, delay) {
  const start = audioContext.currentTime + (delay || 0);
  const source = audioContext.createBufferSource();
  source.buffer = noiseBuffer;
  const filter = audioContext.createBiquadFilter();
  filter.type = filterType;
  filter.frequency.value = filterFrequency;
  const gain = audioContext.createGain();
  gain.gain.setValueAtTime(volume, start);
  gain.gain.exponentialRampToValueAtTime(0.0001, start + duration);
  source.connect(filter);
  filter.connect(gain);
  gain.connect(masterGain);
  source.start(start);
  source.stop(start + duration + 0.02);
}

function roar(amount, duration) {
  if (!crowdGain) return;
  const now = audioContext.currentTime;
  crowdGain.gain.cancelScheduledValues(now);
  crowdGain.gain.setTargetAtTime(CROWD_BASE + amount, now, 0.05);
  crowdGain.gain.setTargetAtTime(CROWD_BASE, now + duration, 0.4);
}

// name: start, whistle, final, jump, land, lane, tackle, hit, win, perfect, kick, net, goal, save, post
export function playSound(name) {
  if (!ensureAudio()) return;
  try {
    switch (name) {
      case 'start':
      case 'whistle':
        playTone(2000, 2300, 0.25, 'sine', 0.12, 0);
        playTone(2000, 2300, 0.45, 'sine', 0.12, 0.3);
        break;
      case 'final':
        playTone(2100, 2300, 0.25, 'sine', 0.13, 0);
        playTone(2100, 2300, 0.25, 'sine', 0.13, 0.35);
        playTone(2100, 2300, 0.7, 'sine', 0.13, 0.7);
        roar(0.1, 1.2);
        break;
      case 'jump':
        playTone(300, 650, 0.18, 'sine', 0.16, 0);
        break;
      case 'land':
        playNoise(0.1, 0.12, 'lowpass', 400, 0);
        break;
      case 'lane':
        playNoise(0.09, 0.08, 'highpass', 1800, 0);
        break;
      case 'tackle':
        playTone(260, 110, 0.35, 'sawtooth', 0.1, 0);
        playNoise(0.3, 0.1, 'bandpass', 900, 0);
        break;
      case 'hit':
        playNoise(0.45, 0.4, 'lowpass', 700, 0);
        playTone(140, 40, 0.5, 'sine', 0.35, 0);
        roar(0.05, 0.6);
        break;
      case 'win':
        playTone(523, 523, 0.12, 'triangle', 0.16, 0);
        playTone(659, 659, 0.12, 'triangle', 0.16, 0.1);
        playTone(784, 784, 0.2, 'triangle', 0.16, 0.2);
        roar(0.12, 0.7);
        break;
      case 'perfect':
        playTone(784, 784, 0.1, 'triangle', 0.16, 0);
        playTone(988, 988, 0.1, 'triangle', 0.16, 0.08);
        playTone(1175, 1175, 0.1, 'triangle', 0.16, 0.16);
        playTone(1568, 1568, 0.3, 'triangle', 0.16, 0.24);
        roar(0.2, 1.0);
        break;
      case 'kick':
        playNoise(0.12, 0.35, 'lowpass', 900, 0);
        playTone(160, 60, 0.15, 'sine', 0.35, 0);
        break;
      case 'net':
        playNoise(0.35, 0.18, 'highpass', 2500, 0);
        break;
      case 'goal':
        playNoise(0.35, 0.18, 'highpass', 2500, 0);
        playTone(523, 523, 0.15, 'triangle', 0.18, 0.05);
        playTone(659, 659, 0.15, 'triangle', 0.18, 0.2);
        playTone(784, 784, 0.15, 'triangle', 0.18, 0.35);
        playTone(1047, 1047, 0.5, 'triangle', 0.18, 0.5);
        playTone(220, 220, 0.9, 'sawtooth', 0.05, 0.1);
        roar(0.4, 2.2);
        break;
      case 'save':
        playNoise(0.15, 0.3, 'lowpass', 1200, 0);
        playTone(300, 200, 0.2, 'triangle', 0.2, 0);
        roar(0.1, 0.8);
        break;
      case 'post':
        playTone(1500, 900, 0.35, 'triangle', 0.2, 0);
        playNoise(0.1, 0.15, 'highpass', 3000, 0);
        roar(0.08, 0.6);
        break;
      default:
        break;
    }
  } catch (error) {
    // Sound is optional: never break the game because of it.
  }
}

export function toggleMute() {
  muted = !muted;
  if (masterGain) masterGain.gain.value = muted ? 0 : 0.8;
  return muted;
}

export function isMuted() {
  return muted;
}